        if (queuedPatternId >= 0 && currentSample >= pendingSwitchSample) {
            stopAllNotesOnTrack(patterns.find { it.id == activePatternId }?.trackIndex ?: 0)
            activePatternId = queuedPatternId
            queuedPatternId = -1
            pendingSwitchSample = -1L
