                )
            }
        }
    }

    internal fun schedulePatternNotes(
        pattern: Pattern,
        currentSample: Long,
        windowEnd: Long,
        bpm: Float,
        patternStartTickOffset: Long = 0L,
        trackIndex: Int = pattern.trackIndex,
