@Test
fun schedulePatternClip_withPadIndex_callsSchedulePadTrigger() {
    val pattern = Pattern(
        id = 0,
        lengthSteps = 16,
        lengthTicks = 960L,
        notes = listOf(
            NoteEvent(note = 60, velocity = 0.8f, startTick = 0L, durationTicks = TICKS_PER_STEP.toLong(), padIndex = 3)
        )
    )
    controller.loadPatterns(listOf(pattern))

    val clip = PatternClip(
        id = "pc-pad", trackIndex = 0, startTick = 0L,
        durationTicks = 960L, patternId = 0
    )
    val windowEnd = controller.tickToSample(9600, 120f)
    controller.schedulePatternClip(clip, 0L, windowEnd, 120f)

    assertEquals("Should schedule 1 pad trigger",
        1, fakeScheduler.padTriggers.size)
    assertEquals("Pad index should be 3",
        3, fakeScheduler.padTriggers[0].padIndex)
    assertEquals("Velocity should match",
        0.8f, fakeScheduler.padTriggers[0].velocity, 0.001f)
    assertEquals("No noteOn events should be scheduled",
        0, fakeScheduler.noteOnEvents.size)
}

@Test
fun schedulePatternClip_legacyPadIndex_fallsBackToNoteOn() {
    // NoteEvent with padIndex = -1 (legacy) should use noteOn path
    val pattern = Pattern(
        id = 0,
        lengthSteps = 16,
        lengthTicks = 960L,
        notes = listOf(
            NoteEvent(note = 60, velocity = 0.8f, startTick = 0L, durationTicks = TICKS_PER_STEP.toLong(), padIndex = -1)
        )
    )
    controller.loadPatterns(listOf(pattern))

    val clip = PatternClip(
        id = "pc-legacy", trackIndex = 0, startTick = 0L,
        durationTicks = 960L, patternId = 0
    )
    val windowEnd = controller.tickToSample(9600, 120f)
    controller.schedulePatternClip(clip, 0L, windowEnd, 120f)

    assertEquals("Should schedule 1 noteOn",
        1, fakeScheduler.noteOnEvents.size)
    assertEquals("Note should be 60",
        60, fakeScheduler.noteOnEvents[0].note)
    assertEquals("No pad triggers should be scheduled",
        0, fakeScheduler.padTriggers.size)
}

@Test
fun schedulePatternClip_clipPadIndex_overridesNotePadIndex() {
    // Note.padIndex = -1 (legacy), but clip.padIndex = 5
    // The clip's padIndex should be used as the effective padIndex
    val pattern = Pattern(
        id = 0,
        lengthSteps = 16,
        lengthTicks = 960L,
        notes = listOf(
            NoteEvent(note = 60, velocity = 0.8f, startTick = 0L, durationTicks = TICKS_PER_STEP.toLong(), padIndex = -1)
        )
    )
    controller.loadPatterns(listOf(pattern))

    val clip = PatternClip(
        id = "pc-override", trackIndex = 0, startTick = 0L,
        durationTicks = 960L, patternId = 0, padIndex = 5
    )
    val windowEnd = controller.tickToSample(9600, 120f)
    controller.schedulePatternClip(clip, 0L, windowEnd, 120f)

    assertEquals("Should schedule 1 pad trigger",
        1, fakeScheduler.padTriggers.size)
    assertEquals("Pad index should be 5 (from clip)",
        5, fakeScheduler.padTriggers[0].padIndex)
    assertEquals("No noteOn events should be scheduled",
        0, fakeScheduler.noteOnEvents.size)
}

